 pasos=['<b>Contador y llave general</b>: reubica el contador si hace falta y deja la llave general accesible.','<b>Red fría</b>: tubería principal por la pared, con una derivación por aparato.','<b>Termo</b>: se alimenta de la red fría y sale hacia la red caliente. Colócalo cerca de los puntos que más agua caliente usan.','<b>Red caliente</b>: paralela a la fría, <b>por encima</b> de ella y separada al menos 4 cm; aislada.','<b>Llave de corte en cada aparato</b>, accesible, para poder arreglar uno sin cortar toda la vivienda.','<b>Aparatos</b>: lavabo y ducha con fría y caliente, inodoro solo con fría, y en el gabinete el lavamanos clínico y un punto de agua auxiliar.','<b>Prueba de presión</b> antes de cerrar rozas y fotografía de todo el recorrido.'],
 claves=[('Presión en el punto','≥ 100 kPa en grifos; ≥ 150 kPa en fluxores y calentadores; ≤ 500 kPa'),('Agua caliente','50-65 °C en el punto de consumo; acumulador ≥ 60 °C'),('Fría y caliente','Fría por debajo, separadas ≥ 4 cm'),('Retorno de ACS','Si el punto más lejano está a más de 15 m'),('Derivaciones','Ø 12 mm a lavabo, ducha, inodoro y fregadero; Ø 20 mm a lavadora y bañera')],
 no=['Mezclar las dos redes en un mismo tubo sin aislar.','Cerrar las rozas sin prueba de presión.','Llave de corte oculta tras un mueble o una puerta.'],
 si=['Fría y caliente separadas, con la caliente aislada.','Prueba de presión con manómetro y registro fotográfico.','Una llave de corte accesible por aparato y una general señalizada.'],
