 claves=[('Pendiente','2 a 4 % en ramales colectores'),('Diámetros','Inodoro Ø 110; ducha Ø 40; lavabo Ø 32-40'),('Sifón','Uno por aparato, accesible'),('Prueba','De estanquidad con agua antes de cerrar')],
 no=['Desagüe horizontal sin pendiente: se atasca.','Sifón oculto sin registro.','Conectar un ramal a la bajante en ángulo recto.'],
 si=['Pendiente continua del 2 al 4 % hasta la bajante.','Sifones accesibles y registro al pie de la bajante.','Bajante ventilada hasta cubierta.'],
 foto='Red de desagües a la vista con su pendiente, sifones y registros, antes de cubrirla.',
