 claves=[('Instalador','Con certificado de manipulación de gases fluorados'),('Normativa','RITE (Reglamento de Instalaciones Térmicas)'),('Refrigerantes','R32 o R410A, según el equipo')],
 no=['Elegir la potencia "a ojo".','Colocar la unidad exterior sin espacio de servicio.','No prever dónde irá el desagüe de condensados.'],
 si=['Carga térmica calculada por estancia.','Espacio libre alrededor de la unidad exterior.','Desagüe con pendiente prevista desde el proyecto.'],
